"""Browser walkthrough with Playwright (python tests/ui_check.py). Saves screenshots to docs/screenshots."""
import sys, os
import pandas as pd
from playwright.sync_api import sync_playwright
B = "http://localhost:8000"; OUT = "docs/screenshots"; os.makedirs(OUT, exist_ok=True)
df = pd.read_csv("data/transactions.csv"); errs, fails = [], []
def check(n, c, x=""):
    print(("PASS " if c else "FAIL ") + n, x)
    if not c: fails.append(n)
with sync_playwright() as p:
    br = p.chromium.launch(); ctx = br.new_context(viewport={"width": 1440, "height": 900}, accept_downloads=True); pg = ctx.new_page()
    pg.on("console", lambda m: errs.append(m.text) if m.type == "error" else None); pg.on("pageerror", lambda e: errs.append(str(e)))
    pg.goto(B); pg.wait_for_selector(".kpi .value"); pg.wait_for_timeout(1200)
    vals = pg.locator(".kpi .value").all_inner_texts()
    check("overview shows real totals", vals[0] == "5,000" and vals[1] == "2,500", str(vals[:3]))
    check("overview warns sample is balanced", "balanced sample by design" in pg.locator(".banner").first.inner_text())
    check("overview charts drawn", pg.locator("canvas").count() == 3); pg.screenshot(path=f"{OUT}/01_overview.png", full_page=True)
    pg.click("text=Transaction explorer"); pg.wait_for_selector("tbody tr")
    check("table has 25 rows", pg.locator("tbody tr").count() == 25)
    pg.click("button:has-text('Next')"); pg.wait_for_timeout(600); check("pagination -> first id 26", pg.locator("tbody tr").first.locator("td").first.inner_text() == "26")
    pg.select_option("#ps", "50"); pg.wait_for_timeout(600); check("page size 50", pg.locator("tbody tr").count() == 50)
    pg.select_option("#f-source", "PaySim"); pg.wait_for_timeout(500)
    check("type list narrows to PaySim types", pg.locator("#f-type option").count() == 6, str(pg.locator("#f-type option").count()))
    pg.select_option("#f-type", "TRANSFER"); pg.select_option("#f-label", "fraud"); pg.wait_for_timeout(900)
    exp = int(((df.Source == "PaySim") & (df.TransactionType == "TRANSFER") & (df.FraudLabel == 1)).sum())
    txt = pg.locator(".pager span").first.inner_text(); check(f"filters -> {exp} PaySim fraud transfers", str(exp) in txt, txt)
    pg.fill("#f-search", "zzzzzz"); pg.wait_for_timeout(900); check("empty state shown", pg.locator(".empty").count() == 1); pg.screenshot(path=f"{OUT}/03_transactions_empty_state.png")
    pg.click("#f-reset"); pg.wait_for_selector("tbody tr")
    pg.click("th button[data-sort=Amount]"); pg.click("th button[data-sort=Amount]"); pg.wait_for_timeout(800)
    top = pg.locator("tbody tr").first.locator("td").nth(3).inner_text().replace(",", ""); check("sort by Amount desc", abs(float(top) - round(df.Amount.max())) <= 1, top)
    pg.select_option("#f-source", "IEEE-CIS"); pg.select_option("#f-label", "fraud"); pg.wait_for_timeout(800); pg.screenshot(path=f"{OUT}/02_transactions.png")
    with pg.expect_download() as d: pg.click("#f-export")
    e = pd.read_csv(d.value.path()); check("browser CSV export honours filters", len(e) == int(((df.Source == "IEEE-CIS") & (df.FraudLabel == 1)).sum()) and (e.Source == "IEEE-CIS").all(), f"{len(e)} rows")
    pg.click("text=Fraud detection"); pg.wait_for_selector("#examples button"); pg.wait_for_timeout(500)
    pg.click("#p-go"); pg.wait_for_selector(".verdict"); v = pg.locator(".verdict").inner_text().replace("\n", " "); check("prediction renders", "%" in v, v[:70]); pg.screenshot(path=f"{OUT}/04_fraud_detection.png")
    pg.select_option("#p-source", "ULB"); check("type list follows source (ULB)", pg.locator("#p-type option").count() == 1)
    pg.select_option("#p-source", "IEEE-CIS"); check("IEEE label says product code", "Product code" in pg.locator("#lbl-type").inner_text())
    pg.fill("#p-amount", "-5"); pg.click("#p-go"); check("client validation (amount)", "0 or more" in pg.locator("#e-amount").inner_text())
    pg.fill("#p-amount", "50"); pg.fill("#p-hour", "30"); pg.click("#p-go"); check("client validation (hour)", "0 to 23" in pg.locator("#e-hour").inner_text())
    pg.fill("#p-hour", "12"); pg.click("#p-go"); pg.wait_for_selector(".verdict"); check("valid submit after fixing", True)
    pg.click("button:has-text('Real legitimate')"); pg.wait_for_selector(".verdict"); check("legit example scores", True)
    pg.click("nav >> text=Analytics"); pg.wait_for_selector("#a6"); pg.wait_for_timeout(1200); check("Analytics charts", pg.locator("canvas").count() == 6); pg.screenshot(path=f"{OUT}/05_analytics.png", full_page=True)
    pg.click("nav >> text=Model performance"); pg.wait_for_selector("#m3"); pg.wait_for_timeout(1200); check("Performance charts", pg.locator("canvas").count() == 3)
    check("per-source and real-rate tables present", pg.locator("h2:has-text('real-world fraud rates')").count() == 1 and pg.locator("h2:has-text('by source')").count() == 1); pg.screenshot(path=f"{OUT}/06_model_performance.png", full_page=True)
    pg.click("#cm-tabs button >> nth=0"); pg.wait_for_timeout(300); check("confusion matrix switches model", "Logistic" in pg.locator("#cm .hl").inner_text())
    pg.click("#proto button[data-p=random]"); pg.wait_for_selector("#m3"); pg.wait_for_timeout(800); check("random protocol view", "Random 80/20" in pg.locator("p.sub").first.inner_text() or "Random split" in pg.locator("#proto").inner_text())
    pg.click("nav >> text=Reports"); pg.wait_for_selector("#r1")
    for b in ["#r1", "#r2", "#r3"]:
        with pg.expect_download() as d: pg.click(b)
        check("report download " + b, d.value.suggested_filename.endswith(".csv"), d.value.suggested_filename)
    pg.screenshot(path=f"{OUT}/07_reports.png")
    pg.click("nav >> text=Dataset and model"); pg.wait_for_selector("dl.kv"); pg.screenshot(path=f"{OUT}/08_dataset.png", full_page=True)
    check("dataset page shows balanced-by-design caveat", "BALANCED" in pg.locator(".banner").inner_text().upper())
    # ---- AI Explainability page ----
    import requests
    pg.click("nav >> text=AI Explainability"); pg.wait_for_selector("#chat-log"); pg.wait_for_selector(".verdict"); pg.wait_for_timeout(1000)
    check("sidebar keeps all original items", all(pg.locator(f"nav >> text={t}").count() >= 1 for t in ["Overview", "Transaction explorer", "Fraud detection", "Analytics", "Model performance", "Reports", "Dataset and model", "AI Explainability"]))
    check("selector lists dataset transactions", pg.locator("#x-pick option").count() == 100, str(pg.locator("#x-pick option").count()))
    tid = int(pg.locator("#x-pick").input_value()); j = requests.get(f"{B}/api/explain/{tid}").json()
    check("score on screen equals backend model score", f"{j['prediction']['probability'] * 100:.1f}%" in pg.locator(".verdict").inner_text(), f"tx {tid}")
    body = pg.locator("#ex-body").inner_text()
    check("prediction and actual label shown separately", "Model prediction" in body and "Actual label" in body and "Why was this transaction flagged" in pg.locator("main").inner_text())
    check("contribution chart + table present", pg.locator("#ex-chart").count() == 1 and pg.locator("tbody tr").count() == 3)
    check("limitations panel mentions balanced sample and source differences", "Balanced benchmark sample" in body and "Performance differs by source" in body)
    painted = lambda: pg.evaluate("""()=>{const c=document.getElementById('ex-chart');const d=c.getContext('2d').getImageData(0,0,c.width,c.height).data;let n=0;for(let i=0;i<d.length;i+=4){if(d[i+3]>200&&d[i]>150&&d[i+1]<80&&d[i+2]<110)n++}return n}""")
    check("contribution chart is actually painted", painted() > 1000, str(painted()))
    pg.set_viewport_size({"width": 1440, "height": 1750}); pg.wait_for_timeout(1200); pg.screenshot(path=f"{OUT}/10_ai_explainability.png")
    pg.click("#chips button >> nth=1"); pg.wait_for_function("document.querySelectorAll('#chat-log .msg').length>=3 && !document.querySelector('#chat-log .dots')")
    last = pg.locator("#chat-log .msg").last.inner_text(); check("suggested question answered from real contributions", "points" in last and f"transaction #{tid}" in last, last[:60].replace("\n", " "))
    pg.fill("#chat-input", "Is this definitely fraud?"); pg.click("#chat-send"); pg.wait_for_function("document.querySelectorAll('#chat-log .msg').length>=5 && !document.querySelector('#chat-log .dots')")
    check("certainty question refused honestly", "cannot confirm" in pg.locator("#chat-log .msg").last.inner_text())
    pg.fill("#chat-input", "<img src=x onerror=alert(1)>"); pg.click("#chat-send"); pg.wait_for_function("document.querySelectorAll('#chat-log .msg').length>=7 && !document.querySelector('#chat-log .dots')")
    check("HTML in chat is escaped, not executed", pg.locator("#chat-log img").count() == 0)
    pg.click("#chat-send"); check("empty message rejected with notice", "Type a question" in pg.locator("#toast").inner_text())
    check("chart still painted after chatting", painted() > 1000); pg.wait_for_timeout(800); pg.screenshot(path=f"{OUT}/11_ai_chatbot.png"); pg.set_viewport_size({"width": 1440, "height": 900})
    pg.select_option("#x-pick", index=1); pg.wait_for_function("document.querySelector('#chat-log') && !document.querySelector('#chat-log').innerText.includes('Which features')"); pg.wait_for_timeout(600)
    tid2 = int(pg.locator("#x-pick").input_value()); log = pg.locator("#chat-log").inner_text()
    check("chat resets and re-targets when transaction changes", f"#{tid2}" in log and pg.locator("#chat-log .msg.user").count() == 0, log[:70].replace("\n", " "))
    pg.click("#chips button >> nth=0"); pg.wait_for_function("document.querySelectorAll('#chat-log .msg').length>=3 && !document.querySelector('#chat-log .dots')")
    check("new answer refers to the new transaction", f"transaction #{tid2}" in pg.locator("#chat-log .msg").last.inner_text())
    pg.click("#chat-clear"); check("new conversation clears history", pg.locator("#chat-log .msg").count() == 1)
    pg.select_option("#x-group", "fp"); pg.select_option("#x-source", "ULB"); pg.wait_for_timeout(1200)
    n_api = requests.get(f"{B}/api/transactions?label=legit&model_flag=flagged&source=ULB&split=test&page_size=100").json()["total"]
    check("group+source filters match dataset", pg.locator("#x-pick option").count() == min(100, n_api) and "false alarm" in pg.locator("#ex-body").inner_text(), f"{n_api} matching")
    pg.fill("#x-id", "99999"); pg.click("#x-go"); pg.wait_for_timeout(300); check("out-of-range ID rejected in UI", "between 1 and" in pg.locator("#ex-body").inner_text())
    pg.fill("#x-id", "2500"); pg.click("#x-go"); pg.wait_for_selector(".verdict"); check("go-to-ID loads that transaction", "#2500" in pg.locator("#ex-body").inner_text())
    pm = br.new_context(viewport={"width": 390, "height": 800}).new_page(); pm.goto(B + "/#/explain"); pm.wait_for_selector(".verdict"); pm.wait_for_timeout(1000)
    check("explain page mobile: no horizontal overflow", pm.evaluate("document.documentElement.scrollWidth <= window.innerWidth + 1")); pm.screenshot(path=f"{OUT}/12_ai_explainability_mobile.png")
    m = br.new_context(viewport={"width": 390, "height": 800}).new_page(); m.goto(B + "/#/overview"); m.wait_for_selector(".kpi"); m.wait_for_timeout(800)
    check("mobile: no horizontal overflow", m.evaluate("document.documentElement.scrollWidth <= window.innerWidth + 1")); m.screenshot(path=f"{OUT}/09_mobile.png")
    o = ctx.new_page(); o.route("**/api/**", lambda r: r.abort()); o.goto(B); o.wait_for_selector(".banner.err"); check("offline error message", "not reachable" in o.locator(".banner.err").inner_text())
    br.close()
real = [e for e in errs if "favicon" not in e and "422" not in e]
check("no browser console errors", not real, str(real[:3]))
print("\nFAILED:" if fails else "\nALL UI CHECKS PASSED", fails if fails else ""); sys.exit(1 if fails else 0)
